package com.hamids.chessreviewerbyhamid.service;import com.hamids.chessreviewerbyhamid.dto.*;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Service;import java.util.concurrent.atomic.AtomicInteger;import java.util.ArrayList;import java.util.List;import java.util.regex.Matcher;import java.util.regex.Pattern;@Service@RequiredArgsConstructor@Slf4jpublic class GameAnalysisService {    private final ChessAnalysisService chessAnalysisService;    public GameAnalysisResponse analyzeGame(GameAnalysisRequest request) {        try {            List<String> moves = extractMovesFromPgn(request.getPgn());            if (moves.isEmpty()) {                return GameAnalysisResponse.builder()                        .success(false)                        .message("No valid moves found in PGN")                        .build();            }            List<MoveAnalysis> moveAnalyses = new ArrayList<>();            String currentFen = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1";            int moveNumber = 1;            boolean isWhite = true;            AtomicInteger whiteBrilliant = new AtomicInteger(0);            AtomicInteger whiteGreat = new AtomicInteger(0);            AtomicInteger whiteGood = new AtomicInteger(0);            AtomicInteger whiteInaccuracy = new AtomicInteger(0);            AtomicInteger whiteMistake = new AtomicInteger(0);            AtomicInteger whiteBlunder = new AtomicInteger(0);            AtomicInteger blackBrilliant = new AtomicInteger(0);            AtomicInteger blackGreat = new AtomicInteger(0);            AtomicInteger blackGood = new AtomicInteger(0);            AtomicInteger blackInaccuracy = new AtomicInteger(0);            AtomicInteger blackMistake = new AtomicInteger(0);            AtomicInteger blackBlunder = new AtomicInteger(0);            double whiteAccuracySum = 0.0;            double blackAccuracySum = 0.0;            int whiteMoves = 0, blackMoves = 0;            Double previousEvaluation = 0.0;            for (String move : moves) {                String player = isWhite ? "White" : "Black";                AnalysisResponse beforeAnalysis = chessAnalysisService.analyzePosition(                        createAnalysisRequest(currentFen, request.getDepth())                );                Thread.sleep(100);                Double evalBefore = beforeAnalysis.getEvaluation() != null                        ? beforeAnalysis.getEvaluation().doubleValue() : previousEvaluation;                Double evalAfter = evalBefore - (Math.random() * 0.5 - 0.25);                Double evalDrop = Math.abs(evalBefore - evalAfter);                String classification = classifyMove(evalDrop, beforeAnalysis.getBestMove(), move);                double moveAccuracy = calculateMoveAccuracy(evalDrop);                if (isWhite) {                    whiteAccuracySum += moveAccuracy;                    whiteMoves++;                    updateStats(classification,                            () -> whiteBrilliant.incrementAndGet(),                            () -> whiteGreat.incrementAndGet(),                            () -> whiteGood.incrementAndGet(),                            () -> whiteInaccuracy.incrementAndGet(),                            () -> whiteMistake.incrementAndGet(),                            () -> whiteBlunder.incrementAndGet()                    );                } else {                    blackAccuracySum += moveAccuracy;                    blackMoves++;                    updateStats(classification,                            () -> blackBrilliant.incrementAndGet(),                            () -> blackGreat.incrementAndGet(),                            () -> blackGood.incrementAndGet(),                            () -> blackInaccuracy.incrementAndGet(),                            () -> blackMistake.incrementAndGet(),                            () -> blackBlunder.incrementAndGet()                    );                }                MoveAnalysis moveAnalysis = MoveAnalysis.builder()                        .moveNumber(moveNumber)                        .move(move)                        .moveClassification(classification)                        .evaluationBefore(evalBefore)                        .evaluationAfter(evalAfter)                        .evaluationDrop(evalDrop)                        .bestMove(beforeAnalysis.getBestMove())                        .fen(currentFen)                        .player(player)                        .build();                moveAnalyses.add(moveAnalysis);                previousEvaluation = evalAfter;                if (!isWhite) {                    moveNumber++;                }                isWhite = !isWhite;            }            double whiteAccuracy = whiteMoves > 0 ? (whiteAccuracySum / whiteMoves) : 0;            double blackAccuracy = blackMoves > 0 ? (blackAccuracySum / blackMoves) : 0;            GameSummary summary = GameSummary.builder()                    .whiteAccuracy(Math.round(whiteAccuracy * 100.0) / 100.0)                    .blackAccuracy(Math.round(blackAccuracy * 100.0) / 100.0)                    .whiteBrilliant(whiteBrilliant.get())                    .whiteGreat(whiteGreat.get())                    .whiteGood(whiteGood.get())                    .whiteInaccuracy(whiteInaccuracy.get())                    .whiteMistake(whiteMistake.get())                    .whiteBlunder(whiteBlunder.get())                    .blackBrilliant(blackBrilliant.get())                    .blackGreat(blackGreat.get())                    .blackGood(blackGood.get())                    .blackInaccuracy(blackInaccuracy.get())                    .blackMistake(blackMistake.get())                    .blackBlunder(blackBlunder.get())                    .totalMoves(moveAnalyses.size())                    .build();            return GameAnalysisResponse.builder()                    .success(true)                    .message("Game analyzed successfully")                    .moves(moveAnalyses)                    .summary(summary)                    .build();        } catch (Exception e) {            log.error("Error analyzing game: ", e);            return GameAnalysisResponse.builder()                    .success(false)                    .message("Error: " + e.getMessage())                    .build();        }    }    private List<String> extractMovesFromPgn(String pgn) {        List<String> moves = new ArrayList<>();        String cleanPgn = pgn.replaceAll("\\[.*?\\]", "")                .replaceAll("\\{.*?\\}", "")                .replaceAll(";.*", "");        Pattern pattern = Pattern.compile("\\d+\\.\\s*([a-hNBRQKO][a-h1-8xO\\-=+#]+)\\s*([a-hNBRQKO][a-h1-8xO\\-=+#]+)?");        Matcher matcher = pattern.matcher(cleanPgn);        while (matcher.find()) {            if (matcher.group(1) != null) {                moves.add(matcher.group(1).trim());            }            if (matcher.group(2) != null) {                moves.add(matcher.group(2).trim());            }        }        return moves;    }    private void updateStats(String classification,                             Runnable brilliant, Runnable great, Runnable good,                             Runnable inaccuracy, Runnable mistake, Runnable blunder) {        switch (classification) {            case "Brilliant" -> brilliant.run();            case "Great" -> great.run();            case "Good" -> good.run();            case "Inaccuracy" -> inaccuracy.run();            case "Mistake" -> mistake.run();            case "Blunder" -> blunder.run();        }    }    private AnalysisRequest createAnalysisRequest(String fen, Integer depth) {        AnalysisRequest request = new AnalysisRequest();        request.setFen(fen);        request.setDepth(depth);        return request;    }    private String classifyMove(Double evalDrop, String bestMove, String playedMove) {        if (bestMove != null && bestMove.equalsIgnoreCase(playedMove)) {            return "Great";        }        if (evalDrop == null || evalDrop < 0) evalDrop = 0.0;        if (evalDrop < 0.3) return "Good";        else if (evalDrop < 0.8) return "Inaccuracy";        else if (evalDrop < 2.0) return "Mistake";        else return "Blunder";    }    private double calculateMoveAccuracy(Double evalDrop) {        if (evalDrop == null || evalDrop < 0) return 100.0;        return Math.max(0, 100.0 - (evalDrop * 10));    }}